-@js:
var list=[],
a=java.getElements("li.chapter-item a");
for(i in a){
	name=a[i].text()
	link=a[i].attr("href")
	list.push({text:name,href:link})
	}
var url=baseUrl.replace(/\d+.$/,
	"bookchapter/,");
var id=baseUrl.match(/(\d+).$/)[1];
var body=`id=${id}&id2=1`,
post=JSON.stringify({
  "body": String(body),
  "method": "POST"});
var html=java.ajax(url+post),
data=JSON.parse(html);
for($ of data){
	name=$.name
	link=$.id+".html"
	list.push({text:name,href:link})
	}
list

